// Janela de trabalho: 9h–18h, segunda a sexta (horário São Paulo)
const now = new Date();
const spOffset = -3; // GMT-3
const spHour = (now.getUTCHours() + spOffset + 24) % 24;
const dayOfWeek = now.getUTCDay(); // 0 = domingo, 6 = sábado
const isBusinessHour = spHour >= 9 && spHour < 18;
const isBusinessDay = dayOfWeek >= 1 && dayOfWeek <= 5;
if (!isBusinessHour || !isBusinessDay) {
  return [];
}
return [{ json: { ok: true, hora_sp: spHour } }];

const lead = $input.item.json;
const props = lead.property || lead.properties || {};
const getText = (key) => {
  const p = props[key];
  if (!p) return '';
  if (p.title) return p.title.map(t => t.plain_text).join('');
  if (p.rich_text) return p.rich_text.map(t => t.plain_text).join('');
  if (p.select) return p.select?.name || '';
  if (p.status) return p.status?.name || '';
  if (p.phone_number) return p.phone_number;
  if (p.url) return p.url;
  if (p.email) return p.email;
  return '';
};
const lead_id = lead.id;
const nome = getText('Nome');
const empresa = getText('Empresa');
const cargo = getText('Cargo');
const whatsapp = getText('WhatsApp');
const gatilho = getText('Gatilho de prospecção');
const setor = getText('Setor');
const faturamento = getText('Faturamento estimado');
const instagram = getText('Instagram');
const site = getText('Site da empresa');
const linkedin = getText('LinkedIn');
const historico = getText('Histórico');
return { json: { lead_id, nome, empresa, cargo, whatsapp, gatilho, setor, faturamento, instagram, site, linkedin, historico, is_first_touch: !historico } };

