const claudeResp = $input.item.json;
const leadData = $('Extrai dados do lead').item.json;
let parsed;
try {
  const text = claudeResp.content[0].text.trim();
  const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '');
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    mensagem_proposta: '[ERRO de parsing — revisar manualmente]',
    raciocinio: 'Falha no parsing: ' + e.message,
    score_sugerido: '🟡 Warm',
    proxima_etapa_sugerida: 'Aguardando aprovação',
    alerta_humano: 'Claude retornou JSON inválido. Resposta crua: ' + (claudeResp.content?.[0]?.text || '').slice(0, 300)
  };
}
return { json: { ...leadData, ...parsed } };
